arguments.file_text:
#:property AllowUnsafeBlocks=true

Console.WriteLine($"nint size: {nint.Size} bytes");

Span<nint> span = stackalloc nint[5];
for (int i = 0; i < span.Length; i++)
    span[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"  [{i}] = {span[i]}");

Span<nuint> uspan = stackalloc nuint[3];
uspan[0] = nuint.MinValue;
uspan[1] = 42;
uspan[2] = nuint.MaxValue;

Console.WriteLine("Span<nuint> via stackalloc:");
for (int i = 0; i < uspan.Length; i++)
    Console.WriteLine($"  [{i}] = {uspan[i]}");

